events.command:
Rscript -e '
res <- readRDS("/workspace/res_1vs98.rds")
cat("Type:", typeof(res), "\n")
cat("Is S4:", isS4(res), "\n")
cat("Slots:", toString(slotNames(res)), "\n")
for(s in slotNames(res)) {
  cat("\n--- Slot:", s, "---\n")
  val <- slot(res, s)
  cat("  Class:", class(val), "\n")
  cat("  Type:", typeof(val), "\n")
  if(is.atomic(val) && length(val) < 20) {
    cat("  Values:", toString(val), "\n")
  } else if(is(val, "DataFrame") || is(val, "data.frame")) {
    cat("  Cols:", toString(colnames(val)), "\n")
    cat("  Dims:", nrow(val), "x", ncol(val), "\n")
    cat("  First rows:\n")
    print(head(val, 3))
  }
}
'

