events.command:
Rscript -e '
# Try reading without triggering S4 class dispatch
x <- readRDS("/workspace/res_1vs97.rds")
# Access underlying list structure directly
cat("attributes:", toString(attributes(x)), "\n")
# Try .Data slot
d <- x@.Data
cat("Is list:", is.list(d), "\n")
cat("Length:", length(d), "\n")
cat("Names:", toString(names(d)), "\n")
if(is.list(d)) {
  for(i in seq_along(d)) {
    nm <- names(d)[i]
    cat("\n---", nm, "---\n")
    if(is.atomic(d[[i]])) {
      cat("  First few:", toString(head(d[[i]], 5)), "\n")
    } else {
      cat("  Class:", class(d[[i]]), "\n")
    }
  }
}
'

